window.HUB.extras.writing = [
  { level: "A2", title: "Ma journée type", prompt: "Décris une journée normale de ta semaine : à quelle heure tu te lèves, comment tu vas en cours, ce que tu manges, ce que tu fais le soir. Utilise le présent simple et des adverbes de fréquence (always, usually, sometimes, never).", words: "60–80" },
  { level: "A2", title: "Mon week-end dernier", prompt: "Raconte ton dernier week-end à un ami anglais : où tu es allé, avec qui, ce que tu as fait et ce que tu en as pensé. Utilise le past simple, avec des verbes réguliers et irréguliers.", words: "60–80" },
  { level: "A2", title: "Premier email à un correspondant", prompt: "Écris un premier email à un(e) correspondant(e) britannique : présente-toi (âge, ville, famille, études), parle de tes loisirs et pose-lui trois questions. Registre amical, avec une formule d'ouverture et de clôture.", words: "60–80" },
  { level: "A2", title: "Ma ville", prompt: "Décris ta ville ou ton quartier pour un touriste : ce qu'il y a (there is / there are), les endroits à visiter, ce qu'on peut y faire. Termine par ce que tu aimes et ce que tu n'aimes pas.", words: "60–80" },
  { level: "A2", title: "Mes projets de vacances", prompt: "Explique tes projets pour les prochaines vacances : où tu vas aller, avec qui, combien de temps et ce que tu vas faire. Utilise going to pour les projets et will pour une prédiction.", words: "60–80" },
  { level: "A2", title: "Une personne que j'admire", prompt: "Décris une personne que tu admires (famille, ami, célébrité) : son apparence, son caractère et pourquoi tu l'admires. Utilise des adjectifs variés et au moins un comparatif.", words: "60–80" },
  { level: "B1", title: "Email : excuse et proposition", prompt: "Tu ne peux pas aller à la fête d'anniversaire d'un ami anglais. Écris-lui un email : excuse-toi, explique pourquoi, propose une autre sortie et fixe une date. Registre amical.", words: "120–150" },
  { level: "B1", title: "Les réseaux sociaux et les études", prompt: "Écris un court article pour le journal de ton établissement sur les avantages et les inconvénients des réseaux sociaux pour les étudiants. Donne ton avis en reliant tes idées avec however, although, because et so.", words: "120–150" },
  { level: "B1", title: "Une histoire qui commence mal", prompt: "Écris une histoire qui commence par cette phrase : « It was the worst morning of my life. » Utilise le past simple, le past continuous et au moins un past perfect.", words: "120–150" },
  { level: "B1", title: "Critique de film ou de série", prompt: "Écris une critique d'un film ou d'une série que tu as vu récemment pour un site anglophone : l'histoire (sans tout dévoiler), les acteurs, ce que tu as aimé ou non, et ta recommandation finale.", words: "120–150" },
  { level: "B1", title: "Une expérience qui m'a fait grandir", prompt: "Raconte une expérience qui t'a fait grandir (un voyage, un échec, une rencontre). Utilise le present perfect pour présenter l'expérience et le past simple pour raconter les détails.", words: "120–150" },
  { level: "B1", title: "Candidature pour un job d'été", prompt: "Tu postules pour un job d'été dans un café à Londres. Écris un email semi-formel : présente-toi, explique ta motivation, tes qualités, ton expérience éventuelle et tes disponibilités.", words: "120–150" },
  { level: "B2", title: "Faut-il interdire le téléphone à l'école ?", prompt: "Rédige un essai argumenté sur la question « Should mobile phones be banned in schools? ». Présente les deux points de vue avec des exemples concrets et conclus avec ton opinion. Registre neutre, paragraphes bien structurés.", words: "180–220" },
  { level: "B2", title: "Lettre de réclamation", prompt: "Tu as commandé en ligne un produit arrivé cassé et en retard. Écris une lettre formelle au service client : décris le problème, ce que tu as déjà tenté, et ce que tu attends (remboursement ou échange).", words: "180–220" },
  { level: "B2", title: "Rapport : améliorer la cantine", prompt: "Le directeur de ton établissement te demande un rapport en anglais sur la cantine : situation actuelle, problèmes signalés par les élèves, recommandations. Utilise des intertitres et la voix passive.", words: "180–220" },
  { level: "B2", title: "Un lieu qui a changé", prompt: "Écris un article de magazine sur un lieu de ton enfance qui a beaucoup changé : comment il était (used to, would), ce qui a changé, ce que tu ressens. Exprime au moins un regret avec wish ou if only.", words: "180–220" },
  { level: "B2", title: "Une décision à refaire", prompt: "Réponds à la question « If you could change one decision in your life, what would it be? ». Utilise le troisième conditionnel et au moins un conditionnel mixte pour imaginer les conséquences.", words: "180–220" },
  { level: "B2", title: "Candidature Erasmus", prompt: "Écris la partie « motivation » d'une candidature à un programme d'échange universitaire : ton parcours, pourquoi ce pays, ce que tu apporteras et ce que tu espères en retirer. Registre formel.", words: "180–220" },
  { level: "C1", title: "L'IA et l'éducation", prompt: "Rédige un essai discursif sur l'affirmation « Artificial intelligence will do more harm than good to education. ». Discute les deux côtés avec nuance, utilise des marqueurs de cohésion (furthermore, nonetheless, that said) et au moins une inversion.", words: "220–260" },
  { level: "C1", title: "Proposition au conseil municipal", prompt: "Écris une proposition formelle au conseil municipal pour créer un espace jeunes dans ta ville : constat, objectifs, coût estimé, bénéfices attendus. Utilise des tournures impersonnelles et le subjonctif (It is essential that every young person have access to…).", words: "220–260" },
  { level: "C1", title: "Critique littéraire", prompt: "Écris la critique d'un livre qui t'a marqué pour une revue culturelle : contexte, thèmes, style de l'auteur, limites, et le public à qui tu le recommandes. Varie le vocabulaire évaluatif.", words: "220–260" },
  { level: "C1", title: "Lettre au rédacteur en chef", prompt: "Un journal anglais affirme que les jeunes ne lisent plus. Écris une lettre au rédacteur en chef pour nuancer ou contester cette idée, avec des arguments solides et des exemples précis.", words: "220–260" },
  { level: "C1", title: "Nouvelle à chute", prompt: "Écris une nouvelle courte avec une fin inattendue. Utilise des propositions participiales (Having opened the door, she…), des temps narratifs variés et au moins un passage dialogué.", words: "220–260" },
  { level: "C1", title: "Rapport de projet", prompt: "Rédige un rapport synthétique sur un stage ou un projet de groupe : objectifs, déroulement, difficultés rencontrées, leçons tirées, recommandations. Ton professionnel et concis, nominalisations bienvenues.", words: "220–260" },
  { level: "C2", title: "Liberté et sécurité", prompt: "Rédige un essai argumentatif sur la tension entre liberté individuelle et sécurité collective. Construis une argumentation subtile, anticipe les objections et emploie un registre soutenu.", words: "250–300" },
  { level: "C2", title: "Chronique ironique", prompt: "Écris une chronique de journal au ton ironique sur une habitude moderne (le télétravail, les influenceurs, la course aux likes). Joue sur l'euphémisme et la litote sans perdre le fil de ton argument.", words: "250–300" },
  { level: "C2", title: "Discours de remise de diplômes", prompt: "Écris le discours que tu prononcerais lors d'une cérémonie de remise de diplômes : une anecdote, un message central, un appel à l'action. Varie le rythme des phrases et utilise des procédés rhétoriques (rythme ternaire, questions, inversion).", words: "250–300" },
  { level: "C2", title: "Analyse d'un débat de société", prompt: "Analyse un débat de société actuel de ton choix (climat, réseaux sociaux, éducation) : origines, positions en présence, enjeux. Reste équilibré et précis, avec un vocabulaire nuancé.", words: "250–300" },
  { level: "C2", title: "Trois registres", prompt: "Pars de ce message très familier : « hey so the meeting's off, got stuff to sort out, catch you later ». Réécris-le dans trois registres (courriel professionnel, lettre officielle, note amicale), puis commente brièvement tes choix de vocabulaire et de syntaxe.", words: "250–300" },
  { level: "C2", title: "Critique culturelle approfondie", prompt: "Écris la critique approfondie d'une œuvre (film, album, exposition) pour une revue spécialisée : mets-la en contexte, analyse ses choix artistiques et défends un jugement personnel argumenté.", words: "250–300" }
];

